// Controlled provider metadata + real Panel HTTP/AnalysisWorkspace contracts.
// The chain is a test fixture, not a history generated by scientific tools.
// No numerical accuracy, genuine-provider or native-mouse acceptance is claimed.
import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,readdirSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createImagePanel} from '../tools/image_panel.mjs';
import {AnalysisWorkspace,acquireAnalysisWorkspaceOwner,readAnalysisWorkspace,readAnalysisWorkspaceResumeSnapshot,verifyAnalysisReferences} from '../lib/analysis_workspace.mjs';
import {PanelWindowStore} from '../lib/panel_window_collection.mjs';
import {frameAncestryProjection} from '../lib/image_frame_ancestry.mjs';

const id=n=>n.toString(16).padStart(32,'0'),T=id(1),F=id(2),V=id(3),bytes=Buffer.from('89504e470d0a1a0a00000000','hex'),png=bytes.toString('base64');
const hash=value=>createHash('sha256').update(value).digest('hex'),sha=hash(bytes),copy=value=>structuredClone(value);
const mapping={domain:'spatial_pixels',source_object_id:F,source_rect_xyxy:[0,0,64,64],image_rect_xyxy:[0,0,64,64]};
const frame={frame_object_id:F,frame_index:0,source_object_id:T};
const objectBase={backend:'external-image-workspace',state:'completed'};

async function fixture(run,{recordsCount=65,bundled=false,nonemptyLegacy=false,start=true}={}){
 const workspace=mkdtempSync(path.join(tmpdir(),'panel-source-recheck-')),records=new Map(),calls=[],protectedFiles=new Map(),gates=new Set();let panel=null,held=null;
 const save=value=>{const saved={...objectBase,...value};records.set(saved.object_id,copy(saved));const directory=path.join(workspace,'objects',saved.object_id);mkdirSync(directory,{recursive:true});writeFileSync(path.join(directory,'object.json'),JSON.stringify(saved));if(saved.files_sha256)writeFileSync(path.join(directory,'preview.png'),bytes);return saved;};
 save({object_id:T,kind:'tiff_source',request_id:'fixture-source'});save({object_id:F,kind:'frame',source_object_id:T,frame_index:0,request_id:'fixture-frame'});
 save({object_id:V,kind:'view',parent_object_id:F,request_id:'fixture-view',array_domain:'spatial',shape_yx:[64,64],panels:[copy(mapping)],annotations:[],display:{gamma:1},files_sha256:{'preview.png':sha}});
 let root=V;for(let n=0;n<recordsCount-2;n++){const next=id(100+n);save({...copy(records.get(V)),object_id:next,kind:'annotate',parent_object_id:root,render_base_object_id:V,request_id:'fixture-revision-'+n});root=next;}
 const collection=new PanelWindowStore();if(nonemptyLegacy){collection.admit(records.get(V),frame);collection.admit(records.get(root),null);}
 const legacy={schema_version:1,object_id:root,state_revision:4,frame_identity:null,selection:null,edit_state:{draft_revision:2,dirty:false,gesture_active:false,selection:null,annotation_edit:null,base_object_id:root},window_collection:collection.checkpoint(),spatial_return_reference:null,pending_result:null,last_operation:null,numeric_result_refs:{statistics:null,profile:null},window_drafts:{},working_selections:{},adopted_results:[]};
 // Use the real explicit-save writer and hash/readback validation. Only its
 // provider admission callback is controlled to represent the old algorithm.
 const owner=acquireAnalysisWorkspaceOwner(workspace,{role:'gui',owner_id:'fixture-legacy-writer'}),analysis=new AnalysisWorkspace(workspace,legacy,owner);
 try{await analysis.save('legacy-null-save',analysis.status().working_revision,async snapshot=>{assert.deepEqual(snapshot.frame_identity,null);assert.equal(records.has(snapshot.object_id),true);});analysis.close();}finally{owner.release();}
 verifyAnalysisReferences(workspace,readAnalysisWorkspace(workspace).savepoint);
 for(const name of ['origin.json','current.json','savepoints/legacy-null-save.json']){const file=path.join(workspace,'analysis-workspace',...name.split('/'));protectedFiles.set(file,hash(readFileSync(file)));}
 for(const saved of records.values())for(const name of ['object.json',...(saved.files_sha256?['preview.png']:[])]){const file=path.join(workspace,'objects',saved.object_id,name);protectedFiles.set(file,hash(readFileSync(file)));}
 const client=()=>({async rpc(method){return {result:method==='tools/list'?{tools:[{name:'image_info',inputSchema:{properties:bundled?{include_frame_ancestry:{type:'boolean'}}:{}}}]}:{}};},async tool(name,args){
  calls.push({name,args:copy(args)});assert.equal(name,'image_info','source recheck cannot dispatch a scientific write');
  if(held?.object_id===args.object_id){const hold=held;held=null;hold.entered();await hold.wait;}
  const value=records.get(args.object_id);assert.ok(value,'Missing controlled provider object '+args.object_id);const data=copy(value);
  if(args.include_frame_ancestry){const chain=[];let item=data;for(let n=0;n<65;n++){chain.push(frameAncestryProjection(item));if(['frame','tiff_source','dm_source','compare'].includes(item.kind))break;item=records.get(item.parent_object_id??item.base_object_id??item.source_object_id);assert.ok(item);}data.frame_ancestry={schema_version:1,root_object_id:data.object_id,records:chain};}
  return {data,png:value.files_sha256?png:null};
 },async close(){}});
 const open=async()=>{const resume=readAnalysisWorkspaceResumeSnapshot(workspace);panel=await createImagePanel({workspace,python:path.resolve('unused-python'),object_id:resume.object_id,analysis_restore:resume,client:client()});return panel;};
 const state=()=>panel.state();
 const post=async(route,body,{signal}={})=>{const origin=panel.url.split('/#')[0],response=await fetch(origin+route,{method:'POST',headers:{'X-Panel-Token':panel.token,Origin:origin,'Content-Type':'application/json',Connection:'close'},body:JSON.stringify(body),signal});return {status:response.status,data:await response.json()};};
 const actionBody=(action,params={},extra={})=>({expected_object_id:state().object.object_id,draft_revision:state().edit_state.draft_revision,action,params,...extra});
 const act=(action,params={},extra={})=>post('/api/action',actionBody(action,params,extra));
 const work=(action,extra={})=>post('/api/workspace',{action,expected_working_revision:state().workspace_analysis.working_revision,...extra});
 const parameters=request_id=>({request_id,expected_state_revision:state().state_revision,collection_revision:state().window_collection.revision,expected_working_revision:state().workspace_analysis.working_revision});
 const assertProtected=({afterNewSave=false,except=[]}={})=>{for(const [file,digest]of protectedFiles)if(!except.includes(file)&&!(afterNewSave&&file===path.join(workspace,'analysis-workspace','current.json')))assert.equal(hash(readFileSync(file)),digest,'original file changed: '+path.relative(workspace,file));};
 const h={workspace,root,records,calls,state,post,act,work,parameters,actionBody,open,assertProtected,get panel(){return panel;},async reopen(){await panel.close();panel=null;return open();},hold(object_id=root){let release,entered;const wait=new Promise(resolve=>release=resolve),started=new Promise(resolve=>entered=resolve);gates.add(release);held={object_id,wait,entered};return {release,started};}};
 try{if(start)await open();await run(h);}finally{for(const release of gates)release();if(panel)await panel.close();assert.equal(path.dirname(workspace),path.resolve(tmpdir()));rmSync(workspace,{recursive:true,force:true});}
}

test('legacy 65-record saved-null stays unqualified until explicit read-only recheck, then saves a new point and reopens',async()=>{
 for(const bundled of [false,true])await fixture(async h=>{
  const before=h.state(),old=readAnalysisWorkspace(h.workspace).savepoint;assert.equal(before.frame_identity,null);assert.equal(before.source_recheck.status,'available');assert.equal(before.source_recheck.records_checked,65);assert.equal(before.frame_resolution.status,'recheck_required');assert.equal(before.window_collection.windows.length,0);assert.equal(before.workspace_analysis.dirty,false);h.assertProtected();
  const checked=await h.act('recheck-source',h.parameters('explicit-source-check'));assert.equal(checked.status,200,checked.data.error);assert.deepEqual(checked.data.frame_identity,frame);assert.equal(checked.data.source_recheck,undefined);assert.equal(checked.data.workspace_analysis.dirty,true);assert.equal(checked.data.workspace_analysis.save_id,'legacy-null-save');assert.equal(checked.data.object.object_id,h.root);assert.equal(checked.data.window_collection.windows.length,1);assert.equal(checked.data.window_collection.windows[0].role,'source');assert.equal(checked.data.window_collection.windows[0].object_id,h.root);assert.equal(checked.data.edit_state.draft_revision,before.edit_state.draft_revision+1);assert.deepEqual(readAnalysisWorkspace(h.workspace).savepoint,old);h.assertProtected();
  const count=h.calls.length,query=await h.act('query-source-recheck',{request_id:'explicit-source-check'});assert.equal(query.status,200,query.data.error);assert.equal(query.data.source_recheck_query.state,'completed');assert.equal(query.data.source_recheck_query.automatic_retry,false);assert.equal(query.data.source_recheck_query.applied_to_current_working,true);assert.equal(h.calls.length,count,'query reads the original local receipt');
  const saved=await h.work('save',{save_id:'requalified-new-save'});assert.equal(saved.status,200,saved.data.error);assert.equal(saved.data.workspace_analysis.dirty,false);assert.deepEqual(readAnalysisWorkspace(h.workspace).savepoint.snapshot.frame_identity,frame);h.assertProtected({afterNewSave:true});
  const closed=await h.work('close');assert.equal(closed.status,200,closed.data.error);await h.reopen();assert.deepEqual(h.state().frame_identity,frame);assert.equal(h.state().source_recheck,undefined);assert.equal(h.state().workspace_analysis.save_id,'requalified-new-save');assert.equal(h.state().workspace_analysis.recovery_available,false);assert.equal(h.state().window_collection.windows[0].object_id,h.root);h.assertProtected({afterNewSave:true});assert.ok(h.calls.every(call=>call.name==='image_info'));
 },{bundled});
});

test('saved-null compatibility refuses shorter chains and retained old windows rather than accepting any null frame',async()=>{
 for(const options of [{recordsCount:13},{recordsCount:64},{recordsCount:65,nonemptyLegacy:true}])await fixture(async h=>{await assert.rejects(h.open(),/frame.*differs|frame.*match/i);h.assertProtected();assert.ok(h.calls.every(call=>call.name==='image_info'));},{...options,start:false});
});

test('discard after source recheck returns the exact old saved-null analysis and queries cannot regrant source qualification',()=>fixture(async h=>{
 const old=readAnalysisWorkspace(h.workspace).savepoint,request='check-before-discard',checked=await h.act('recheck-source',h.parameters(request));assert.equal(checked.status,200,checked.data.error);assert.deepEqual(checked.data.frame_identity,frame);assert.equal(checked.data.workspace_analysis.dirty,true);
 const discarded=await h.work('discard');assert.equal(discarded.status,200,discarded.data.error);assert.equal(discarded.data.object.object_id,h.root);assert.equal(discarded.data.frame_identity,null);assert.equal(discarded.data.source_recheck.status,'available');assert.equal(discarded.data.frame_resolution.status,'recheck_required');assert.equal(discarded.data.window_collection.windows.length,0);assert.equal(discarded.data.window_collection.active_window_id,null);assert.equal(discarded.data.workspace_analysis.save_id,'legacy-null-save');assert.equal(discarded.data.workspace_analysis.dirty,false);assert.deepEqual(readAnalysisWorkspace(h.workspace).savepoint,old);h.assertProtected();
 const count=h.calls.length,oldQuery=await h.act('query-source-recheck',{request_id:request});assert.equal(oldQuery.status,409,'an existing receipt outside the current operation scope must not adopt its former frame');assert.equal(h.state().frame_identity,null);assert.equal(h.state().source_recheck.status,'available');assert.equal(h.state().workspace_analysis.dirty,false);assert.equal(h.calls.length,count);
 const unknown=await h.act('query-source-recheck',{request_id:'not-admitted-after-discard'});assert.equal(unknown.status,200,unknown.data.error);assert.deepEqual(unknown.data.source_recheck_query,{state:'not_journaled_here',request_id:'not-admitted-after-discard',automatic_retry:false,scope:'current_helper_only'});assert.equal(h.state().frame_identity,null);assert.equal(h.state().window_collection.windows.length,0);h.assertProtected();
 const closed=await h.work('close');assert.equal(closed.status,200,closed.data.error);await h.reopen();assert.equal(h.state().frame_identity,null);assert.equal(h.state().source_recheck.status,'available');assert.equal(h.state().workspace_analysis.dirty,false);assert.deepEqual(readAnalysisWorkspace(h.workspace).savepoint,old);h.assertProtected();assert.ok(h.calls.every(call=>call.name==='image_info'));
}));

test('source recheck checks object, draft, state, window and working CAS before admitting an original operation',()=>fixture(async h=>{
 const before=h.state(),old=readAnalysisWorkspace(h.workspace).savepoint;
 for(const [index,mutate]of [p=>{p.params.expected_state_revision++;},p=>{p.params.collection_revision++;},p=>{p.params.expected_working_revision++;},p=>{p.draft_revision++;},p=>{p.expected_object_id=id(999);}].entries()){
  const body=h.actionBody('recheck-source',h.parameters('stale-source-'+index));mutate(body);const count=h.calls.length,result=await h.post('/api/action',body);assert.equal(result.status,409,result.data.error);assert.equal(h.calls.length,count,'stale input must fail before provider reads');assert.equal(h.state().frame_identity,null);assert.equal(h.state().workspace_analysis.dirty,false);assert.deepEqual(readAnalysisWorkspace(h.workspace).savepoint,old);assert.equal(h.state().edit_state.draft_revision,before.edit_state.draft_revision);h.assertProtected();
 }
}));

test('wrong frame and corrupt saved PNG reject source qualification and leave old null references queryable',async()=>{
 for(const fault of ['frame','png'])await fixture(async h=>{
  const current=h.state(),wrongPng=path.join(h.workspace,'objects',h.root,'preview.png');if(fault==='frame')h.records.get(F).frame_index=1;else writeFileSync(wrongPng,Buffer.from('89504e470d0a1a0a01010101','hex'));
  const request='reject-'+fault,result=await h.act('recheck-source',h.parameters(request));assert.equal(result.status,409,result.data.error);assert.equal(h.state().frame_identity,null);assert.equal(h.state().workspace_analysis.dirty,false);assert.equal(h.state().object.object_id,current.object.object_id);assert.equal(h.state().window_collection.windows.length,0);
  const query=await h.act('query-source-recheck',{request_id:request});assert.equal(query.status,200,query.data.error);assert.equal(query.data.source_recheck_query.state,'failed');assert.equal(query.data.source_recheck_query.automatic_retry,false);assert.equal(query.data.source_recheck_query.applied_to_current_working,false);h.assertProtected({except:fault==='png'?[wrongPng]:[]});assert.ok(h.calls.every(call=>call.name==='image_info'));
 });
});

test('a newer direct draft during source recheck rejects commit and keeps the newer edit without scientific writes',{timeout:15000},()=>fixture(async h=>{
 const before=h.state(),gate=h.hold(),checking=h.act('recheck-source',h.parameters('late-draft-source'));
 try{await Promise.race([gate.started,checking.then(result=>assert.fail('Source read did not reach the controlled gate: '+result.status))]);const draft=await h.act('draft',{draft_revision:before.edit_state.draft_revision+1,dirty:true,gesture_active:false,selection:null,confirm_persistence:true});assert.equal(draft.status,200,draft.data.error);}finally{gate.release();}
 const result=await checking;assert.equal(result.status,409,result.data.error);assert.equal(h.state().frame_identity,null);assert.equal(h.state().edit_state.dirty,true);assert.equal(h.state().edit_state.draft_revision,before.edit_state.draft_revision+1);assert.equal(h.state().window_collection.windows.length,0);assert.equal(h.state().workspace_analysis.save_id,'legacy-null-save');h.assertProtected();const query=await h.act('query-source-recheck',{request_id:'late-draft-source'});assert.equal(query.status,200,query.data.error);assert.equal(query.data.source_recheck_query.state,'failed');assert.equal(query.data.edit_state.dirty,true);assert.ok(h.calls.every(call=>call.name==='image_info'));
}));

test('an aborted HTTP response is recovered by the exact original local request, without repeating source admission or science',{timeout:15000},()=>fixture(async h=>{
 const gate=h.hold(),controller=new AbortController(),request='aborted-source-response',body=h.actionBody('recheck-source',h.parameters(request)),aborted=h.post('/api/action',body,{signal:controller.signal}).then(()=>assert.fail('Controlled aborted response unexpectedly arrived'),error=>error);
 await gate.started;controller.abort();const error=await aborted;assert.equal(error.name,'AbortError');gate.release();
 const deadline=Date.now()+5000;while(h.state().last_operation?.state==='source_recheck_pending'&&Date.now()<deadline)await new Promise(resolve=>setTimeout(resolve,5));assert.equal(h.state().last_operation?.state,'source_recheck_completed');
 const before=h.calls.length,query=await h.act('query-source-recheck',{request_id:request});assert.equal(query.status,200,query.data.error);assert.equal(query.data.source_recheck_query.state,'completed');assert.equal(query.data.source_recheck_query.automatic_retry,false);assert.equal(query.data.source_recheck_query.applied_to_current_working,true);assert.equal(h.calls.length,before);
 const operation=copy(h.state().last_operation),foreign=await h.act('query-source-recheck',{request_id:'another-source-request'});assert.equal(foreign.status,200,foreign.data.error);assert.deepEqual(foreign.data.source_recheck_query,{state:'not_journaled_here',request_id:'another-source-request',automatic_retry:false,scope:'current_helper_only'});assert.deepEqual(h.state().last_operation,operation,'absence in this helper must not resolve or replace the original operation');assert.equal((await h.act('recheck-source',h.parameters(request))).status,409);assert.equal(h.calls.length,before);
 const requests=readdirSync(h.panel.journal).filter(name=>name.endsWith('.source-check.request.json'));assert.deepEqual(requests,[request+'.source-check.request.json']);assert.deepEqual(h.state().frame_identity,frame);assert.equal(h.state().workspace_analysis.save_id,'legacy-null-save');h.assertProtected();assert.ok(h.calls.every(call=>call.name==='image_info'));
}));
